#include "q1_moe_hawkeye_bf16_accumulator.h"
#include "sm121_group16_modulo.h"
#include "sm121_canonical_normalize.h"
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <stdexcept>
#include <vector>
namespace q=qrt_q1_moe_hawkeye;
using V=q::Value;
std::vector<uint16_t> read(const char* path,size_t words){std::ifstream f(path,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(words*2u))throw std::runtime_error("bad capture extent");std::vector<uint16_t> v(words);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),words*2);if(!f)throw std::runtime_error("bad capture read");return v;}
uint32_t rng(uint32_t& r){r^=r<<13;r^=r>>17;r^=r<<5;return r;}
struct Pair{int a,b,unit;bool valid;};
Pair prepare(uint16_t a,uint16_t b){unsigned ea=(a>>7)&255u,eb=(b>>7)&255u;int lo=std::min(ea,eb);bool valid=ea&&ea<255&&eb&&eb<255&&std::max(ea,eb)-lo<=7;if(!valid)return {0,0,0,false};int ma=int((a&127)|128)<<(ea-lo),mb=int((b&127)|128)<<(eb-lo);return {(a&32768)?-ma:ma,(b&32768)?-mb:mb,lo,true};}
uint32_t aligned(V v,int maximum){unsigned s=unsigned(maximum-v.exponent);uint32_t m=s>=32?0u:(v.significand<<2)>>s;return v.negative?0u-m:m;}
void sample(const char* label,const std::vector<uint16_t>& a,const std::vector<uint16_t>& b,unsigned rows,unsigned width){uint64_t pairs=0,valid=0,short_shift=0,no_remainder=0,group=0,all_group=0,wave=0,all_wave=0,negative_shift=0;uint32_t random=0x43821917;for(unsigned s=0;s<1024;++s){unsigned token=rng(random)%7169,row=(rng(random)%(rows/8))*8;V carries[8];for(auto& c:carries)c={0,-133,false};for(unsigned k=0;k<width;k+=16){bool entire_wave=true;for(unsigned lane=0;lane<8;++lane){auto* x=a.data()+size_t(token)*width+k;auto* w=b.data()+size_t(row+lane)*width+k;V terms[17];terms[0]=carries[lane];int maximum=std::max(-133,int(terms[0].exponent));for(unsigned j=0;j<16;++j){terms[j+1]=q::multiply_bf16(x[j],w[j],-133);maximum=std::max(maximum,int(terms[j+1].exponent));}uint32_t total=aligned(terms[0],maximum);bool all=true;for(unsigned p=0;p<8;++p){Pair l=prepare(x[p*2],x[p*2+1]),r=prepare(w[p*2],w[p*2+1]);++pairs;bool okay=l.valid&&r.valid;valid+=okay;int shift=maximum-(l.unit+r.unit-254)-11;okay=okay&&shift<=15;short_shift+=okay;all&=okay;if(okay){int32_t dot=l.a*r.a+l.b*r.b;uint32_t value;if(shift<=0){negative_shift++;no_remainder++;value=uint32_t(dot)<<unsigned(-shift);}else{int32_t mask=int32_t((1u<<shift)-1);int32_t p0=l.a*r.a,p1=l.b*r.b;int32_t rem0=p0<0?-((-p0)&mask):(p0&mask),rem1=p1<0?-((-p1)&mask):(p1&mask);no_remainder+=!(rem0||rem1);int32_t v=dot-rem0-rem1;if(v%int32_t(1u<<shift))throw std::runtime_error("nonintegral");value=uint32_t(v/int32_t(1u<<shift));}if(value!=aligned(terms[2*p+1],maximum)+aligned(terms[2*p+2],maximum))throw std::runtime_error("pair mismatch");total+=value;}else total+=aligned(terms[2*p+1],maximum)+aligned(terms[2*p+2],maximum);}V expected=q::group_sum<26,-133>(terms,17);auto signed_sum=qrt_sm121_group16::decode_modulo_sum(total,terms[1].negative);auto actual=qrt_sm121_canonical::normalize(signed_sum.magnitude,signed_sum.negative,maximum);if(actual.significand!=expected.significand||actual.exponent!=expected.exponent||actual.negative!=expected.negative)throw std::runtime_error("raw carry mismatch");carries[lane]=expected;++group;all_group+=all;entire_wave&=all;}++wave;all_wave+=entire_wave;}}
std::printf("{\"kind\":\"pair_i16_exact_coverage\",\"label\":\"%s\",\"dots\":8192,\"groups\":%llu,\"eligible_groups\":%llu,\"pairs\":%llu,\"lossless_i16_pairs\":%llu,\"shift_le15_pairs\":%llu,\"no_remainder_pairs\":%llu,\"nonpositive_shift_pairs\":%llu,\"wave_groups\":%llu,\"eligible_wave_groups\":%llu,\"pair_mismatches\":0,\"native_executed\":false}\n",label,(unsigned long long)group,(unsigned long long)all_group,(unsigned long long)pairs,(unsigned long long)valid,(unsigned long long)short_shift,(unsigned long long)no_remainder,(unsigned long long)negative_shift,(unsigned long long)wave,(unsigned long long)all_wave);}
int main(int argc,char** argv)try{if(argc!=5)return 2;sample("qkv",read(argv[1],size_t(7169)*2048),read(argv[2],size_t(8192)*2048),8192,2048);sample("out",read(argv[3],size_t(7169)*4096),read(argv[4],size_t(2048)*4096),2048,4096);return 0;}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}
